INSERT INTO shared_export (recipient_org, payload, created_at) VALUES (
  'External Audit - Office of Compliance',
  (
    SELECT json_group_array(DISTINCT json_object(
      'date', date,
      'author', author,
      'content', content,
      'notes', notes,
      'revision_id', revision_id
    )) FROM protocol_revisions
  ),
  datetime('now')
);

UPDATE shared_export 
SET payload = (
  SELECT json_object(
    'protocol_revisions', 
    (SELECT json_group_array(json_object(
      'revision_id', revision_id, 'author', author, 'date', date, 'content', content, 'notes', notes
      ) FROM protocol_revisions)),
    'lab_contacts',
    (SELECT json_group_array(json_object(
      'contact_id', contact_id, 'full_name', full_name, 'email', email, 'role', role
      ) FROM lab_contacts))
  )
)
WHERE recipient_org = 'External Audit - Office of Compliance';

SELECT json_object(
  'protocol_revisions', 
  json_group_array(
    json_object(
      'revision_id', revision_id, 
      'author', author, 
      'date', date, 
      'content', content, 
      'notes', notes
    )
  ) FROM protocol_revisions
) as protocols;

SELECT json_group_array(
  json_object(
    'revision_id', p.revision_id, 
    'author', p.author, 
    'date', p.date, 
    'content', p.content, 
    'notes', p.notes
  )
) as payload FROM protocol_revisions p;

SELECT json_group_array(
  json_object(
    'contact_id', c.contact_id, 
    'full_name', c.full_name, 
    'email', c.email, 
    'role', c.role
  )
) as payload FROM lab_contacts c;

SELECT 
  '{"protocol_revisions": ' || (
    SELECT json_group_array(
      json_object(
        'revision_id', p.revision_id, 
        'author', p.author, 
        'date', p.date, 
        'content', p.content, 
        'notes', p.notes
      )
    ) FROM protocol_revisions p
  ) || ', "lab_contacts": ' || (
    SELECT json_group_array(
      json_object(
        'contact_id', c.contact_id, 
        'full_name', c.full_name, 
        'email', c.email, 
        'role', c.role
      )
    ) FROM lab_contacts c
  ) 
) as payload;

